before:
flowchart LR
    A@{ shape: "parallelogram", label: "Tiles in" }
    B@{ shape: 'parallelogramAlt', label: "Tiles out" }
    A --> B

after:
flowchart LR
    A@{ shape: "lean-r", label: "Tiles in" }
    B@{ shape: 'lean-l', label: "Tiles out" }
    A --> B

before:
flowchart LR
    A@{ shape: trapezoidAlt, label: "Funnel" }
    A --> B[Done]

after:
flowchart LR
    A@{ shape: trap-t, label: "Funnel" }
    A --> B[Done]

before:
flowchart TD
    end@{ shape: rhombus, label: "Last color" }
    A[Start] --> end

after:
flowchart TD
    endNode@{ shape: diamond, label: "Last color" }
    A[Start] --> endNode

before:
flowchart TD
    A@{ shape: diamond, label: "Pick color" }
